function [Mp_AC, phi_AC, VcClk, vcRegulated, VsClk, regCapture] = fcn_regulate_Vc(vcReg, Mp_AC, phi_AC, VcClkRef)
%FCN_REGULATE_VC keeps the converter voltage v_c at a fixed amplitude and
%phase by correcting the AC source command Mp_AC and phi_AC.
%   v_s is generated by a power amplifier + transformer, and the switch
%   closed after the sync adds a voltage drop between v_s and v_c, so the
%   voltage seen by the converter changes with the current. Regulating v_c
%   (instead of v_s) gives the converter an ideal grid at its terminals.
%   The DAC output (amplifier input) is measured on the same PicoScope as v_c,
%   so the DAC phasor gives the internal oscillator phase within each capture.
%   Adding phi_AC (known) gives the phase of v_c relative to the internal
%   oscillator, which is also the reference of phi_m of the converter.
%
%   VcClkRef: v_c phasor in the oscillator frame to hold (taken at no load,
%   at the end of the sync).
%
%   vcReg: struct with the devices (ts, ps4000aDeviceObj, numChannels,
%   probeVoltsPerUnit, idxVc, idxVs, idxVdac, dtScope, f0) and the tuning
%   (TolV, TolPhi, Alpha, MaxStepM, MaxStepPhi, MaxIter, Settle_s, Mmax, Vmax).
%
%   Returns the Mp_AC/phi_AC applied to the board, the last measured VcClk,
%   whether the tolerances were met, and VsClk (v_s in the oscillator frame,
%   same last capture) to quantify the voltage drop |V_s - V_c| across the
%   switch, which is printed at the end.
%   regCapture: the last capture (fields t, v_c, v_dac, Mp_AC, phi_AC), to
%   compare it with the sync reference (fcn_plot_vc_regulation).

clip = @(x, lim) min(max(x, -lim), lim);

Mp_AC_start = Mp_AC;
phi_AC_start = phi_AC;
vcRegulated = false;

for it = 1:vcReg.MaxIter

    vcReg.ts.write("Config", struct("wMpAC", Mp_AC));
    vcReg.ts.write("Config", struct("wphi_AC", phi_AC));
    Mp_AC_written = Mp_AC;
    phi_AC_written = phi_AC;
    pause(vcReg.Settle_s);

    [~, ~, channelData, ~] = picoscope_acquisition(vcReg.ps4000aDeviceObj, vcReg.numChannels);
    Vc = fcn_FundamentalPhasor(channelData{vcReg.idxVc} / vcReg.probeVoltsPerUnit(vcReg.idxVc), vcReg.dtScope, vcReg.f0);
    Vs = fcn_FundamentalPhasor(channelData{vcReg.idxVs} / vcReg.probeVoltsPerUnit(vcReg.idxVs), vcReg.dtScope, vcReg.f0);
    Vdac = fcn_FundamentalPhasor(channelData{vcReg.idxVdac} / vcReg.probeVoltsPerUnit(vcReg.idxVdac), vcReg.dtScope, vcReg.f0);

    % Keep this capture with the AC source command applied during it
    regCapture.v_c = channelData{vcReg.idxVc} / vcReg.probeVoltsPerUnit(vcReg.idxVc);
    regCapture.v_dac = channelData{vcReg.idxVdac} / vcReg.probeVoltsPerUnit(vcReg.idxVdac);
    regCapture.t = (0:numel(regCapture.v_c) - 1).' * vcReg.dtScope;
    regCapture.Mp_AC = Mp_AC;
    regCapture.phi_AC = phi_AC;

    % v_c and v_s phasors in the internal oscillator frame: removes the random
    % phase of the capture start (via the DAC phasor) and adds the known DAC phase
    VcClk = Vc * conj(Vdac) / abs(Vdac) * exp(1j * phi_AC);
    VsClk = Vs * conj(Vdac) / abs(Vdac) * exp(1j * phi_AC);
    VcRms = abs(VcClk);
    ePhi = angle(VcClk / VcClkRef);   % > 0 : v_c leads its reference

    fprintf('Vc reg %2d | Mp_AC %.4f phi_AC %+.4f | Vc %5.2f V rms (ref %5.2f) | phase error %+6.2f deg\n', ...
        it, Mp_AC, phi_AC, VcRms, abs(VcClkRef), rad2deg(ePhi));

    if VcRms > vcReg.Vmax
        vcReg.ts.write("Config", struct("wMpAC", Mp_AC_start));
        vcReg.ts.write("Config", struct("wphi_AC", phi_AC_start));
        error('Vc regulation aborted: v_c above %.1f V rms, Mp_AC and phi_AC set back to their values before the regulation.', vcReg.Vmax);
    end

    % End criteria: v_c back to its reference in amplitude and phase
    if abs(VcRms - abs(VcClkRef)) < vcReg.TolV && abs(ePhi) < vcReg.TolPhi
        vcRegulated = true;
        break;
    end

    % Amplitude: proportional correction using the gain V/M
    Mp_AC = min(max(Mp_AC + clip(vcReg.Alpha * (abs(VcClkRef) - VcRms) * Mp_AC / VcRms, vcReg.MaxStepM), 0), vcReg.Mmax);

    % Phase: v_c follows phi_AC about one to one (same oscillator as the DAC)
    phi_AC = angle(exp(1j * (phi_AC - clip(vcReg.Alpha * ePhi, vcReg.MaxStepPhi))));   % keep in (-pi, pi]

end

if ~vcRegulated
    % Return the values that are actually applied (the last update was not written)
    Mp_AC = Mp_AC_written;
    phi_AC = phi_AC_written;
    warning('Vc regulation: tolerances not met after %d iterations.', vcReg.MaxIter);
end

% Voltage drop between v_s and v_c (switch + cables), from the last capture
fprintf('Switch drop | V_s = %.2f V rms, V_c = %.2f V rms | |V_s - V_c| = %.3f V rms | phase(V_s) - phase(V_c) = %+.3f deg\n', ...
    abs(VsClk), abs(VcClk), abs(VsClk - VcClk), rad2deg(angle(VsClk / VcClk)));

end
